def check_greater(arr, number):
    success_message = "Number is strictly greater than every element in the array."
    failure_message = "Number is not strictly greater than every element in the array."
    if all(number > x for x in arr):
        return success_message
    else:
        return failure_message

from typing import Iterable, List

def add_string(items: Iterable[str], prefix: str) -> List[str]:
    return [prefix + item for item in items]
